import re;
import unicodedata;

obj InitialValuesType {
    has caseSensitive: bool;
}

def compute(input: str, options: InitialValuesType) -> str {
    text = input if options.caseSensitive else input.lower();
    text = unicodedata.normalize("NFD", text);
    text = re.sub(r"[\u0300-\u036f]", "", text);
    text = text.strip();
    text = re.sub(r"[^\w\s-]", "", text);
    text = re.sub(r"[\s_-]+", "-", text);
    text = re.sub(r"^-+|-+$", "", text);
    return text;
}

def:pub slugGenerator(input: str, options: InitialValuesType) -> str {
    lines = input.split("\n");
    result = ["" if line.strip() == "" else compute(line, options) for line in lines];
    return "\n".join(result);
}
