"""Quiz grader: walk quiz nodes and collect strictly typed integer score reports."""

node Quiz {
    has student_name: str = "";
    has score: int = 0;
}

walker Grader {
    has report: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    can grade with Quiz entry {
        self.report.append(here.score);
        print(f"Graded {here.student_name}: {here.score}");
        visit [-->] else { disengage; };
    }
}

with entry {
    root ++> Quiz(student_name="Alice", score=92)
        ++> Quiz(student_name="Bob", score=85)
        ++> Quiz(student_name="Carol", score=78)
        ++> Quiz(student_name="Dave", score=96);

    grader = Grader();
    root spawn grader;

    total = 0;
    for s in grader.report {
        total += s;
    }
    count = len(grader.report);
    avg = total / count if count > 0 else 0.0;

    print(f"Collected scores: {grader.report}");
    print(f"Class average: {avg:.1f}");
}
