                <div className="flex items-center gap-2 min-w-0">
                  <Icon className={`w-4 h-4 shrink-0 ${colorClass}`} />
                  <span className="text-sm font-medium text-text-light-primary dark:text-text-dark-primary truncate">
                    {doc.title}
