import from "store" { AppState }
import from "react-redux" { connect }
import from "components/Common/Task" { default as Task }
import from "store/tasks/types" { ITaskState }
import from "store/tasks/actions" { dragAndDrop }
import from "store/show/selectors" { getKanbanOption }
import from "components/Common/TaskWrapper/Button" { default as Button }
import from "components/Common/Icons/Common/Oval" { default as IconOval }

glob variables = {"color": "#0062ff", "colorBorder": "#e2e2ea", "crossSize": 16};
glob mapDispatchToProps = {"dragAndDrop": dragAndDrop};

def mapStateToProps(state: AppState) -> dict[str, bool] {
    return {"option": getKanbanOption(state)};
}

def:pub TaskWrapper(
    title: str,
    tasks: list[ITaskState],
    option: bool,
    dragAndDrop: Callable[[dict[str, object]], None],
) -> JsxElement {
    has dragOver: bool = False;
    wrapperCls = "task-wrapper" + (" task-wrapper-kanban" if option else "");
    tasksBg = (
        "repeating-linear-gradient(45deg, white, white 5px, #E3ECFB 5px, #E3ECFB 10px)"
        if dragOver
        else "white"
    );
    def handle_drag_over(e: DragEvent) {
        e.preventDefault();
        dragOver = True;
    }
    def handle_drag_leave(_e: DragEvent) { dragOver = False; }
    def handle_drop(e: DragEvent) {
        e.preventDefault();
        dragOver = False;
        dragAndDrop({"title": title, "event": e});
    }
    <div className={wrapperCls}>
        <div className="task-wrapper-header">
            <span className="task-wrapper-title">{title}</span>
            <div className="task-wrapper-more">
                <IconOval />
            </div>
        </div>
        <div
            className="task-wrapper-tasks"
            style={{"background": tasksBg}}
            onDragOver={handle_drag_over}
            onDragLeave={handle_drag_leave}
            onDrop={handle_drop}
        >
            {for (i, task) in enumerate(tasks) {
                <Task key={str(i)} data={task} />
            }}
        </div>
        <Button />
    </div>
}

glob:pub default = connect(mapStateToProps, mapDispatchToProps)(TaskWrapper);
