    if len(segmentsToRender) > len(letters) {
        console.warn(f"react-7-segment-display: Segment count {len(segmentsToRender)} out of bounds for letters array.");
    }
    return <div className="digit" style={style}>{[Segment(active=active, color=color, height=height, id=letter, skew=skew) for (letter, active) in zip(letters, segmentsToRender)]}</div>;
}

