def getFirstValue[ListItem](
    list: list[ListItem],
    getValue: Callable[[ListItem, dict[str, bool | int]], bool | str | int | None],
) -> tuple[bool | str | int | None, ListItem | None] {
    firstValue: bool | str | int | None = None;
    listLength = len(list) - 1;
    listItem: ListItem | None = None;
    for (index, item) in enumerate(list) {
        isLast = index == listLength;
