const renderAsCSV = (selected: Array<string>) => selected.join(", ");

const renderAsChips = (selected: Array<string>) => (
    <Box sx={{ display: "flex", flexWrap: "wrap", gap: 0.5 }}>
        {selected.map((value) => (
            <Chip key={value} label={value} />
        ))}
    </Box>
