export function useObjectState<T>(initialState: T) {
  const [state, setState] = useState(initialState);
  function setSafeState(
    newState: Partial<T> | ((prev:T) => Partial<T>),
    callback?: () => void
  ){
    if (typeof newState === "function") {
      setState(prevState => ({
        ...prevState,
        ...newState(prevState)
      }));
    } else {
      setState(prevState => ({
        ...prevState,
        ...newState
      }));
    }

    if (callback) {
      callback();
    }
  };
  return [state, setSafeState];
}

