          stopTimer()
        } else {
          setNow(now - 1)
        }
      }, REFRESH_INTERVAL)
    }
  }

  React.useEffect(() => {
    syncTimer()
    return () => {
      if (countdown.current) {
        clearInterval(countdown.current)
        countdown.current = null
      }
    }
  }, [now])

  return (
    <span className={classNames(sizeClass[size ?? 'middle'])}>
      {formatDate(new Date(RESET_TIME + now * 1000), format ?? 'HH:mm:ss')}
