def:pub getRelativeMousePositionOnCanvas(params: GetRelativeMousePositionOnCanvasParams) -> dict[str, float] {
    windowMouseX = params.windowMouseX;
    windowMouseY = params.windowMouseY;
    canvasWorkingSize = params.canvasWorkingSize;
    scrollPosition = params.scrollPosition;
    zoom = params.zoom;
    zoomRatio = zoom / 100;

    canvasNewWidth = canvasWorkingSize.width * zoomRatio;
    canvasNewHeight = canvasWorkingSize.height * zoomRatio;
    gutterX = (canvasWorkingSize.width - canvasNewWidth) / 2;
    gutterY = (canvasWorkingSize.height - canvasNewHeight) / 2;
    relativeMouseX = (windowMouseX - scrollPosition.x - gutterX) / zoomRatio;
    relativeMouseY = (windowMouseY - scrollPosition.y - gutterY) / zoomRatio;
    return {"relativeMouseX": relativeMouseX, "relativeMouseY": relativeMouseY};
}

