def subscribeToLocationUpdates(callback: Callable[[], None]) -> Callable[[], None] {
    for event in events {
        addEventListener(event, callback);
    }
    return lambda {
        for event in events {
            removeEventListener(event, callback);
        }
    };
}

def useLocationProperty(fn: Callable[[], object], ssrFn: Callable[[], object | None]) -> object {
    return useSyncExternalStore(subscribeToLocationUpdates, fn, ssrFn);
}

def useSearch(opts: dict[str, str | None] | None = None) -> str {
    if opts is None {
        opts = {};
    }
    ssrSearch = opts.get("ssrSearch");
    if ssrSearch is not None {
        return useLocationProperty(currentSearch, lambda { ssrSearch }) as str;
    }
    return useLocationProperty(currentSearch, currentSearch) as str;
}

def usePathname(opts: dict[str, str | None] | None = None) -> str {
    if opts is None {
        opts = {};
    }
    ssrPath = opts.get("ssrPath");
    if ssrPath is not None {
        return useLocationProperty(currentPathname, lambda { ssrPath }) as str;
    }
    return useLocationProperty(currentPathname, currentPathname) as str;
}

def useHistoryState() -> object | None {
    return useLocationProperty(currentHistoryState, lambda { None });
}

def navigate(to: str, opts: dict[str, bool | object | None] | None = None) {
    if opts is None {
        opts = {};
    }
    replace = opts.get("replace") or False;
    state = opts.get("state");
    if replace {
        history.replaceState(state, "", to);
    } else {
        history.pushState(state, "", to);
    }
}

def useBrowserLocation(opts: dict[str, str | None] | None = None) -> list[object] {
    return [usePathname(opts), navigate];
}

def patchHistoryMethod(type: str) {
    original = getattr(history, type);
    patched = lambda (state: object | None, _title: str, url: str) {

        original.call(history, state, _title, url);
        evt = new(Event, type);
        dispatchEvent(evt);
    };
    setattr(history, type, patched);
}

