        } elif suffix == "GB" {
            exp = 30;
        } else {
            raise ValueError('split_size has to end with either' '"MB" or "GB"');
        }
        split_size = int(float(split_size[:-2]) * (2 ** exp));
    }
    if split_size > MAX_SPLIT_SIZE {
        raise ValueError('split_size cannot be larger than 2GB');
    }
    return split_size;
}

