node Pet {
    has name: str = "";
    has species: str = "";
    has needs_vaccine: bool = False;
}

walker Vet {
    has patient_names: list[str] = [];
    has shots_given: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can examine with Pet entry {
        self.patient_names.append(here.name);
        if here.needs_vaccine {
            self.shots_given += 1;
            print(f"[SHOT] {here.name} the {here.species} received a vaccine");
        } else {
            print(f"[CHECK] {here.name} the {here.species} — no shot needed");
        }
        visit [-->] else { disengage; }
    }
}

with entry {
