type ColorsMap = dict[str, Callable[[str], str]];

def _hex_color(_code: str) -> Callable[[str], str] {
    return lambda (message: str) -> str { message; };
}

def _yellow_bright(message: str) -> str {
    return message;
}

def _green_bright(message: str) -> str {
    return message;
}

glob colors: ColorsMap = {
    "error": _hex_color("#ff8383"),
    "errorLight": _hex_color("#ffd3d3"),
    "warn": _yellow_bright,
    "success": _green_bright,
    "highlight": _yellow_bright,
    "subdued": _hex_color("#999"),
};

def makeColor(hasColor: bool) -> MakeColor {
    if not hasColor {
        return lambda (message: str, _colorType: ColorType = "error") -> str { message; };
    }
    return lambda (message: str, colorType: ColorType = "error") -> str { colors[colorType](message); };
}

def spaced(string: str) -> str {
    return f"\n\n{string}\n";
}

def warning(string: str) -> str {
    return colors["error"](f"✕ {string}");
}

def logGeneralError(error: str | tuple[ColorValue, str]) -> str {
    if isinstance(error, tuple) {
        head = error[0];
        tail = error[1];
        headText = head(colors) if callable(head) else head;
        rendered = headText if isinstance(headText, str) else str(headText);
        return spaced(f"{warning(rendered)}\n\n{tail}");
    }
    return spaced(warning(error));
}

def createDebug(isDev: bool, twinConfig: TwinConfigAll) -> Callable[[str, object, ColorType], None] {
    def debug(reference: str, data: object, colorType: ColorType = "subdued") -> None {
        if not isDev {
            return;
        }
        if not twinConfig.debug {
            return;
        }
        log = f"{colors[colorType]('-')} {reference} {colors[colorType](str(data))}";
        print(log);
    }
    return debug;
}
