obj Box {
    has x: float;
    has y: float;
    has w: float;
    has h: float;
}

obj MarkRect {
    has x: float;
    has y: float;
    has width: float;
    has height: float;
}

obj NormRect {
    has x: float;
    has y: float;
    has w: float;
    has h: float;
}

type Point = dict[str, float];

glob:pub IDENTITY: Matrix = [1, 0, 0, 1, 0, 0];

def:pub multiply(a: Matrix, b: Matrix) -> Matrix {
    return [
        (a[0] * b[0]) + (a[1] * b[2]),
        (a[0] * b[1]) + (a[1] * b[3]),
        (a[2] * b[0]) + (a[3] * b[2]),
        (a[2] * b[1]) + (a[3] * b[3]),
        ((a[4] * b[0]) + (a[5] * b[2])) + b[4],
        ((a[4] * b[1]) + (a[5] * b[3])) + b[5],
    ];
}

def:pub translation(tx: float, ty: float) -> Matrix {
    return [1, 0, 0, 1, tx, ty];
}

def:pub quadBounds(m: Matrix, x0: float, y0: float, x1: float, y1: float) -> Box {
    xs: list[float] = [
        (m[0] * x0) + (m[2] * y0) + m[4],
        (m[0] * x1) + (m[2] * y0) + m[4],
        (m[0] * x0) + (m[2] * y1) + m[4],
        (m[0] * x1) + (m[2] * y1) + m[4],
    ];
    ys: list[float] = [
        (m[1] * x0) + (m[3] * y0) + m[5],
        (m[1] * x1) + (m[3] * y0) + m[5],
        (m[1] * x0) + (m[3] * y1) + m[5],
        (m[1] * x1) + (m[3] * y1) + m[5],
    ];
    x: float = min(*xs);
    y: float = min(*ys);
    x_max: float = max(*xs);
    y_max: float = max(*ys);
    return Box(x=x, y=y, w=x_max - x, h=y_max - y);
}

def:pub intersectionArea(a: Box, b: Box) -> float {
    w: float = min(a.x + a.w, b.x + b.w) - max(a.x, b.x);
    h: float = min(a.y + a.h, b.y + b.h) - max(a.y, b.y);
    return (w * h) if ((w > 0) and (h > 0)) else 0.0;
}

def:pub overlapsAny(box: Box, rects: list[Box]) -> bool {
    return any([intersectionArea(box, r) > 0.000001 for r in rects]);
}

def:pub coveredFraction(box: Box, rects: list[Box]) -> float {
    area = box.w * box.h;
    if area <= 0 {
        return 0.0;
    }
    best_frac = 0.0;

    for r in rects {
        best_frac = max(best_frac, intersectionArea(box, r) / area);
    }
    return best_frac;
}

