glob FILE = "style-presets.json";

async def load() -> any {
    return readDataSafe(FILE, {"presets": []});
}

async def save(data: any) -> any {
    await writeData(FILE, data);
}

async def:pub listPresets() -> any {
    data = await load();
    return data.presets;
}

async def:pub createPreset(params: any) -> any {
    data = await load();
    preset: any = {**params, "id": generateId(), "createdAt": now()};
    data.presets.append(preset);
    await save(data);
    return preset;
}

async def:pub deletePreset(id: str) -> any {
    data = await load();
    idx = data.presets.findIndex(lambda (p: any) -> any { return (p.id == id); });
    if (idx == -1) {
        return false;
    }
    data.presets.splice(idx, 1);
    await save(data);
    return true;
}

