  reason?: SessionEndReasonInput,
): SessionEndReason {
  if (reason === "INTERVIEW_TIME_LIMIT_REACHED") {
    return "INTERVIEW_TIME_LIMIT_REACHED";
  }
  if (
    reason === "ACCOUNT_SESSION_TIME_LIMIT_REACHED" ||
