        ++> Quiz(student="Bob", score=74)
        ++> Quiz(student="Cara", score=95)
        ++> Quiz(student="Dan", score=61);
    grader = Grader();
    root spawn grader;
    print(f"Scores: {grader.scores}");
    count = len(grader.scores);
    if count > 0 {
        total = sum(grader.scores);
        avg = total / count;
        print(f"Class average: {avg}");
    } else {
        print("Class average: N/A (no quizzes)");
    }
